/**
 * STRATA service worker.
 *
 * Strategy, in one paragraph: the app shell is precached at install (the manifest is generated by
 * `vite.sw.config.ts` from the real build output, so it cannot list a file that does not exist),
 * navigations are served network-first with a cached shell as the offline fallback, and everything
 * else is cache-first with a background refresh. The multiplayer WebSocket is never cached or
 * intercepted, and nothing is ever sent to a third party: the cache holds only same-origin files.
 *
 * Why network-first for navigations: a game on a phone is usually launched from the home screen;
 * when the network is there, the newest build should win, and when it is not, the cached shell must
 * still open. Static assets keep their hashed names, so cache-first is safe for them.
 *
 * The worker is built as a classic (IIFE) script so browsers without module-worker support can
 * still install it.
 */
declare const __PRECACHE_MANIFEST__: string[];
declare const __BUILD_VERSION__: string;

/** Nothing below runs outside the service-worker build step. */

const CACHE_PREFIX = 'strata-v1';
const PRECACHE: readonly string[] =
  typeof __PRECACHE_MANIFEST__ !== 'undefined' && Array.isArray(__PRECACHE_MANIFEST__)
    ? __PRECACHE_MANIFEST__
    : ['./'];
const VERSION: string = typeof __BUILD_VERSION__ === 'string' ? __BUILD_VERSION__ : 'dev';
const CACHE_NAME = `${CACHE_PREFIX}-${VERSION}`;
const OFFLINE_FALLBACK = './index.html';

interface ExtendableEventLike extends Event {
  waitUntil(promise: Promise<unknown>): void;
}

interface FetchEventLike extends ExtendableEventLike {
  readonly request: Request;
  respondWith(response: Response | Promise<Response>): void;
}

const scope = self as unknown as {
  addEventListener(type: 'install' | 'activate' | 'fetch' | 'message', listener: (event: never) => void): void;
  skipWaiting(): Promise<void>;
  clients: { claim(): Promise<void>; matchAll(options?: unknown): Promise<Array<{ postMessage(message: unknown): void }>> };
  registration: { scope: string };
};

scope.addEventListener('install', ((event: ExtendableEventLike) => {
  event.waitUntil(
    (async () => {
      const cache = await caches.open(CACHE_NAME);
      // Add entries one at a time so a single 404 cannot abort the whole install.
      const results = await Promise.allSettled(PRECACHE.map((entry) => cache.add(new Request(entry, { cache: 'reload' }))));
      const failed = results.filter((result) => result.status === 'rejected').length;
      if (failed > 0) {
        // Not fatal: partial precache still gives offline play for the files that did land.
        console.warn(`[strata sw] ${failed} of ${PRECACHE.length} precache entries failed`);
      }
      await scope.skipWaiting();
    })(),
  );
}) as never);

scope.addEventListener('activate', ((event: ExtendableEventLike) => {
  event.waitUntil(
    (async () => {
      const names = await caches.keys();
      await Promise.all(
        names
          .filter((name) => name.startsWith(CACHE_PREFIX) && name !== CACHE_NAME)
          .map((name) => caches.delete(name)),
      );
      await scope.clients.claim();
      const clients = await scope.clients.matchAll({ type: 'window' });
      for (const client of clients) {
        client.postMessage({ type: 'strata:ready', version: VERSION });
      }
    })(),
  );
}) as never);

scope.addEventListener('fetch', ((event: FetchEventLike) => {
  const request = event.request;
  if (request.method !== 'GET') return;
  const url = new URL(request.url);
  // Never touch cross-origin traffic or the multiplayer socket.
  if (url.origin !== self.location.origin) return;
  if (url.pathname.endsWith('/ws') || url.protocol === 'ws:' || url.protocol === 'wss:') return;

  if (request.mode === 'navigate') {
    event.respondWith(
      (async () => {
        try {
          const response = await fetch(request);
          void cachePut(request, response.clone());
          return response;
        } catch {
          const cache = await caches.open(CACHE_NAME);
          const cached = (await cache.match(OFFLINE_FALLBACK)) ?? (await cache.match('./'));
          if (cached) return cached;
          return new Response(
            '<!doctype html><meta charset="utf-8"><title>STRATA offline</title>' +
              '<p style="font:16px system-ui;padding:2rem">STRATA has not finished caching on this device yet. Reconnect once, then it will start offline.</p>',
            { status: 200, headers: { 'content-type': 'text/html; charset=utf-8' } },
          );
        }
      })(),
    );
    return;
  }

  event.respondWith(
    (async () => {
      const cache = await caches.open(CACHE_NAME);
      const cached = await cache.match(request);
      if (cached) {
        // Refresh in the background; the player never waits on the network for a cached asset.
        void (async () => {
          try {
            const response = await fetch(request);
            void cachePut(request, response);
          } catch {
            // offline: keep the cached copy
          }
        })();
        return cached;
      }
      try {
        const response = await fetch(request);
        void cachePut(request, response.clone());
        return response;
      } catch {
        return new Response('', { status: 504, statusText: 'offline and not cached' });
      }
    })(),
  );
}) as never);

/** Only same-origin, successful, non-opaque responses are worth caching. */
async function cachePut(request: Request, response: Response): Promise<void> {
  if (!response.ok || response.type === 'opaque') return;
  const url = new URL(request.url);
  if (url.origin !== self.location.origin) return;
  try {
    const cache = await caches.open(CACHE_NAME);
    await cache.put(request, response);
  } catch {
    // Quota or a transient failure: the network copy remains authoritative.
  }
}

scope.addEventListener('message', ((event: { data?: unknown }) => {
  const data = event.data;
  if (typeof data !== 'object' || data === null) return;
  const message = data as { type?: string };
  if (message.type === 'strata:skip-waiting') void scope.skipWaiting();
}) as never);
